def subtract(a, b):
    # Normalize intervals: remove empty ones and merge overlapping ones
    def normalize(intervals):
        if not intervals:
            return []
        # Filter out empty intervals
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []
        # Sort by start point
        valid.sort()
        # Merge overlapping and touching intervals
        merged = [valid[0]]
        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add as new interval
                merged.append([start, end])
        return merged

    # Normalize both inputs
    a_norm = normalize(a)
    b_norm = normalize(b)

    if not a_norm:
        return []
    if not b_norm:
        return a_norm

    result = []

    for a_start, a_end in a_norm:
        # For each interval in a, subtract all intervals in b
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_norm:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # Check if b interval overlaps with current range
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the parts outside b
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []
    result.sort()
    merged = [result[0]]
    for start, end in result[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

